var gardenNoAdj = function(n, paths) {
    const adj = new Array(n + 1).fill(null).map(() => []);
    for (const [u, v] of paths) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const res = new Array(n).fill(0);
    for (let i = 1; i <= n; i++) {
        const used = new Set();
        for (const neighbor of adj[i]) {
            if (res[neighbor - 1] !== 0) {
                used.add(res[neighbor - 1]);
            }
        }
        for (let color = 1; color <= 4; color++) {
            if (!used.has(color)) {
                res[i - 1] = color;
                break;
            }
        }
    }
    return res;
};
